const NAMES={"CDP": "बाल विकास एवं शिक्षाशास्त्र", "Hindi": "हिंदी", "Sanskrit": "संस्कृत", "SST": "सामाजिक विज्ञान", "Science": "विज्ञान", "Math": "गणित"};
let sub="CDP",i=0,score=0,done=false;
const $=x=>document.getElementById(x);
function load(s){sub=s;i=0;score=0;document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.dataset.s===s));render()}
function render(){
 let x=BANK[sub][i]; $("subject").textContent=NAMES[sub];$("progress").textContent=`प्रश्न ${i+1} / 50`;$("score").textContent=`स्कोर: ${score}`;$("bar").style.width=((i+1)/50*100)+"%";$("question").textContent=x.q;$("concept").style.display="none";$("result").style.display="none";$("next").disabled=true;done=false;
 let box=$("options");box.innerHTML="";
 x.options.forEach((o,j)=>{let b=document.createElement("button");b.className="option";b.innerHTML=`<b>${String.fromCharCode(65+j)}</b><span>${o}</span>`;b.onclick=()=>choose(j);box.appendChild(b)})
}
function choose(j){if(done)return;done=true;let x=BANK[sub][i];document.querySelectorAll(".option").forEach((b,k)=>{if(k===x.answer)b.classList.add("correct");if(k===j&&j!==x.answer)b.classList.add("wrong")});if(j===x.answer){score++;$("result").textContent="✓ WELL DONE! सही उत्तर";$("result").className="result good"}else{$("result").textContent="✗ सही उत्तर: "+x.options[x.answer];$("result").className="result bad"}$("result").style.display="block";$("concept").textContent="Concept: "+x.concept;$("concept").style.display="block";$("score").textContent=`स्कोर: ${score}`;$("next").disabled=false}
function next(){if(i<49){i++;render()}else{$("question").textContent=`${NAMES[sub]} के 50 प्रश्न पूरे हुए। स्कोर: ${score} / 50`;$("options").innerHTML='<div class="finish">अभ्यास पूरा हुआ — विषय फिर से शुरू करने के लिए नीचे क्लिक करें।</div>';$("result").style.display="none";$("concept").style.display="none";$("next").textContent="फिर से शुरू करें";$("next").disabled=false;$("next").onclick=()=>{i=0;score=0;$("next").textContent="अगला प्रश्न →";$("next").onclick=next;render()}}}
$("next").onclick=next;document.querySelectorAll(".tab").forEach(t=>t.onclick=()=>load(t.dataset.s));render();
